-- EVT lua patch for team_dock_formation_menu (common/script/lua/menu/team_dock_formation_menu_7.00.09.00.lua.bin). Graft clean_hud_shirt_number. Generated by research/scripts/menu_assemble.py (build --out patches) from research/grafts/; do not edit by hand.
